import { z } from "zod";

// Billing plans & periods
export const PlanTier = z.enum(["free","base","business","advanced","enterprise"]);
export const BillingPeriod = z.enum(["monthly", "yearly"]);
export type PlanTierT = z.infer<typeof PlanTier>;
export type BillingPeriodT = z.infer<typeof BillingPeriod>;

// Upgrade request/response
export const UpgradeRequest = z.object({
  plan: PlanTier,
  period: BillingPeriod,
  baseUrl: z.string().url(),
  onboarding: z.string().optional(),
});
export type UpgradeRequestT = z.infer<typeof UpgradeRequest>;

export const UpgradeResponse = z.object({
  // Stripe portal sessions produce a URL; new checkout flows can be redirect or session
  redirectUrl: z.string().url().optional(),
  sessionId: z.string().optional(), // e.g. Checkout Session ID
});
export type UpgradeResponseT = z.infer<typeof UpgradeResponse>;

// Payment methods (normalized)
export const PaymentMethodSummary = z.object({
  id: z.string(),
  type: z.enum(["card","us_bank_account","sepa_debit","link","acss_debit"]),
  brand: z.string().optional(),   // e.g., "visa"
  last4: z.string().optional(),
  isDirectDebit: z.boolean(),
  connected: z.boolean(),         // display "Connected"
  displayName: z.string(),        // computed for UI
});
export type PaymentMethodSummaryT = z.infer<typeof PaymentMethodSummary>;

// Invoices (normalized & merged)
export const InvoiceItem = z.object({
  id: z.string(),
  source: z.enum(["subscription","partnerPayout","domainRenewal"]),
  total: z.number(), // in provider minor units or normalized? (see note below)
  createdAt: z.string(), // ISO
  status: z.enum(["paid","failed","pending"]).optional(),
  description: z.string(),
  paymentMethod: z.string().optional(),
  pdfUrl: z.string().url().optional(),
});
export type InvoiceItemT = z.infer<typeof InvoiceItem>;

// Time-series usage points
export const UsagePoint = z.object({
  ts: z.string(),  // ISO string
  value: z.number()
});
export type UsagePointT = z.infer<typeof UsagePoint>;

Note on amounts: keep provider minor units (e.g., cents) to avoid silent rounding. UI can format with utilities. (Matches today's practice in subscription invoices.)
